net.coobird.thumbnailator.name.Rename safeRenamer = new net.coobird.thumbnailator.name.Rename() {
    @Override
    public String apply(String name, net.coobird.thumbnailator.ThumbnailParameter param) {
        int dotIndex = name.lastIndexOf('.');
        String baseName = (dotIndex == -1) ? name : name.substring(0, dotIndex);
        return "thumb_" + baseName + ".jpg";
    }
};

String originalName = "batch_image.png";
String newName = safeRenamer.apply(originalName, null);

assert "thumb_batch_image.jpg".equals(newName) : "Renamer did not produce expected filename, got: " + newName;
System.out.println("__CHECK__ apply " + newName);

